package cn.local.rainreminder;
import android.content.*;import android.graphics.*;import android.view.*;
final class GridCropView extends View {
 final Bitmap image;final RectF selection=new RectF(.09f,.16f,.985f,.91f);RectF shown=new RectF();Paint paint=new Paint(3);int corner=-1,rows=12;
 GridCropView(Context c,Bitmap b){super(c);image=b;setMinimumHeight(400);}
 Rect grid(){return new Rect(Math.round(selection.left*image.getWidth()),Math.round(selection.top*image.getHeight()),Math.min(image.getWidth(),Math.round(selection.right*image.getWidth())),Math.min(image.getHeight(),Math.round(selection.bottom*image.getHeight())));}
 protected void onDraw(Canvas canvas){float scale=Math.min(getWidth()/(float)image.getWidth(),getHeight()/(float)image.getHeight());float w=image.getWidth()*scale,h=image.getHeight()*scale;shown.set((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);canvas.drawBitmap(image,null,shown,paint);RectF r=new RectF(shown.left+selection.left*w,shown.top+selection.top*h,shown.left+selection.right*w,shown.top+selection.bottom*h);paint.setColor(Color.rgb(0,100,80));paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(3);canvas.drawRect(r,paint);paint.setStrokeWidth(1);for(int n=1;n<7;n++)canvas.drawLine(r.left+r.width()*n/7,r.top,r.left+r.width()*n/7,r.bottom,paint);for(int n=1;n<rows;n++)canvas.drawLine(r.left,r.top+r.height()*n/rows,r.right,r.top+r.height()*n/rows,paint);paint.setStyle(Paint.Style.FILL);for(float x:new float[]{r.left,r.right})for(float y:new float[]{r.top,r.bottom})canvas.drawCircle(x,y,12,paint);}
 public boolean onTouchEvent(MotionEvent e){float x=(e.getX()-shown.left)/shown.width(),y=(e.getY()-shown.top)/shown.height();if(e.getAction()==MotionEvent.ACTION_DOWN){float best=99;int k=0;for(float a:new float[]{selection.left,selection.right})for(float b:new float[]{selection.top,selection.bottom}){float d=(a-x)*(a-x)+(b-y)*(b-y);if(d<best){best=d;corner=k;}k++;}getParent().requestDisallowInterceptTouchEvent(true);return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){x=Math.max(0,Math.min(1,x));y=Math.max(0,Math.min(1,y));if(corner<2)selection.left=Math.min(selection.right-.3f,x);else selection.right=Math.max(selection.left+.3f,x);if(corner%2==0)selection.top=Math.min(selection.bottom-.25f,y);else selection.bottom=Math.max(selection.top+.25f,y);invalidate();return true;}if(e.getAction()==MotionEvent.ACTION_UP){getParent().requestDisallowInterceptTouchEvent(false);return true;}return true;}
}
